-- Program templates, paste-in programs, and rest / tempo / demo video per exercise.
-- Run this once in the Supabase SQL editor BEFORE merging the app update that uses it.

-------------------------------------------------------------------------------
-- New exercise details
-------------------------------------------------------------------------------

alter table public.workout_exercises
  add column if not exists rest      text not null default '' check (length(rest) <= 40),
  add column if not exists tempo     text not null default '' check (length(tempo) <= 20),
  add column if not exists video_url text not null default '' check (video_url = '' or (video_url ~* '^https?://' and length(video_url) <= 500));

-------------------------------------------------------------------------------
-- Templates (shared by all coaches; not client data)
-------------------------------------------------------------------------------

create table if not exists public.program_templates (
  id           uuid primary key default gen_random_uuid(),
  name         text not null unique check (length(trim(name)) between 1 and 80),
  description  text not null default '' check (length(description) <= 500),
  notes        text not null default '' check (length(notes) <= 2000),
  -- [{ name, exercises: [{ name, sets, reps, rpe, rest, tempo, notes, video_url }] }]
  workouts     jsonb not null default '[]'::jsonb check (jsonb_typeof(workouts) = 'array'),
  created_by   uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

alter table public.program_templates enable row level security;

create policy "program_templates: coaches read"
  on public.program_templates for select to authenticated
  using ((select public.is_coach()));
create policy "program_templates: coaches write"
  on public.program_templates for all to authenticated
  using ((select public.is_coach()))
  with check ((select public.is_coach()));

create trigger program_templates_touch
  before update on public.program_templates
  for each row execute function public.touch_updated_at();

-------------------------------------------------------------------------------
-- Create a whole program in one go (from a template or a pasted table).
-- Runs with the caller's permissions, so the usual coaching rules apply.
-------------------------------------------------------------------------------

create or replace function public.create_program_from_draft(target uuid, p_name text, p_notes text, p_workouts jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  prog_id uuid;
  wo_id uuid;
  w jsonb;
  e jsonb;
  wi int := 0;
  ei int;
begin
  if jsonb_typeof(p_workouts) <> 'array' or jsonb_array_length(p_workouts) = 0 then
    raise exception 'The program has no workouts' using errcode = '22023';
  end if;
  insert into public.programs (client_id, name, notes)
  values (target, trim(p_name), coalesce(p_notes, ''))
  returning id into prog_id;
  for w in select * from jsonb_array_elements(p_workouts) loop
    insert into public.program_workouts (program_id, name, position)
    values (prog_id, trim(w->>'name'), wi)
    returning id into wo_id;
    wi := wi + 1;
    ei := 0;
    for e in select * from jsonb_array_elements(coalesce(w->'exercises', '[]'::jsonb)) loop
      insert into public.workout_exercises (workout_id, position, name, target_sets, target_reps, target_rpe, rest, tempo, notes, video_url)
      values (
        wo_id, ei, trim(e->>'name'),
        nullif(e->>'sets', '')::smallint,
        coalesce(e->>'reps', ''),
        nullif(e->>'rpe', '')::numeric,
        coalesce(e->>'rest', ''),
        coalesce(e->>'tempo', ''),
        coalesce(e->>'notes', ''),
        coalesce(e->>'video_url', '')
      );
      ei := ei + 1;
    end loop;
  end loop;
  return prog_id;
end;
$$;

revoke execute on function public.create_program_from_draft(uuid, text, text, jsonb) from public, anon;
grant execute on function public.create_program_from_draft(uuid, text, text, jsonb) to authenticated;

