  ('Beginner Full Body 3x (Home Gym)', 'For home gyms with a barbell, bench and dumbbells. No squat rack needed.', 'Train 3 days a week with at least 1 rest day in between. No squat rack or spotter at home, so never bench press a barbell: use dumbbells or the floor press. RPE 7 means you could have done about 3 more reps. When you hit the top of the rep range on every set, go a little heavier next time.', '[{"name":"Day A","exercises":[{"name":"Goblet squat","sets":3,"reps":"8-12","rpe":7,"rest":"90s","tempo":"3-1-1","notes":"Sit down between your heels, chest tall","video_url":""},{"name":"Dumbbell bench press","sets":3,"reps":"8-10","rpe":7,"rest":"90s","tempo":"3-0-1","notes":"Shoulder blades squeezed together","video_url":""},{"name":"Barbell bent-over row","sets":3,"reps":"8-10","rpe":7,"rest":"90s","tempo":"2-1-1","notes":"Hinge to about 45 degrees, pull to your belly button","video_url":""},{"name":"Barbell Romanian deadlift","sets":3,"reps":"8-10","rpe":7,"rest":"2 min","tempo":"3-0-1","notes":"Bar slides down your thighs, flat back","video_url":""},{"name":"Plank","sets":3,"reps":"20-30s","rpe":7,"rest":"60s","tempo":"","notes":"Squeeze glutes, ribs down","video_url":""}]},{"name":"Day B","exercises":[{"name":"Dumbbell reverse lunge","sets":3,"reps":"8 each leg","rpe":7,"rest":"90s","tempo":"2-0-1","notes":"Step back, front knee over the foot","video_url":""},{"name":"Barbell floor press","sets":3,"reps":"8-10","rpe":7,"rest":"90s","tempo":"2-1-1","notes":"Pause when your upper arms touch the floor","video_url":""},{"name":"One-arm dumbbell row","sets":3,"reps":"10 each arm","rpe":7,"rest":"60-90s","tempo":"2-1-1","notes":"Hand and knee on the bench, pull to your hip","video_url":""},{"name":"Barbell hip thrust","sets":3,"reps":"10-12","rpe":7,"rest":"90s","tempo":"2-1-1","notes":"Upper back on the bench, pad the bar","video_url":""},{"name":"Side plank","sets":3,"reps":"20s each side","rpe":7,"rest":"60s","tempo":"","notes":"Hips high, body in a straight line","video_url":""}]},{"name":"Day C","exercises":[{"name":"Dumbbell step-up","sets":3,"reps":"8 each leg","rpe":7,"rest":"90s","tempo":"2-0-1","notes":"Low bench or step, drive through the front heel","video_url":""},{"name":"Seated dumbbell shoulder press","sets":3,"reps":"8-10","rpe":7,"rest":"90s","tempo":"2-0-1","notes":"Sit tall on the bench, ribs down","video_url":""},{"name":"Chest-supported dumbbell row","sets":3,"reps":"10-12","rpe":7,"rest":"60-90s","tempo":"2-1-1","notes":"Lie face down on the bench","video_url":""},{"name":"Barbell deadlift","sets":3,"reps":"5-6","rpe":7,"rest":"2 min","tempo":"","notes":"Bar over mid-foot, flat back, push the floor away","video_url":""},{"name":"Dead bug","sets":3,"reps":"8 each side","rpe":6,"rest":"60s","tempo":"","notes":"Lower back stays pressed down","video_url":""}]}]'::jsonb),
  ('Dumbbells & Bands Full Body 3x (Home)', 'A pair of dumbbells and resistance bands. Glute and posture friendly, great for most female clients starting at home.', 'Train 3 days a week with at least 1 rest day in between. Pick dumbbells you can lift for the top of the rep range with 2 to 3 reps to spare. Too easy? Lower slower (3 to 4 seconds) or add a pause before going heavier. Anchor bands in a closed door or around a sturdy post. RPE 7 means you could have done about 3 more reps. When you hit the top of the rep range on every set, go a little heavier next time.', '[{"name":"Day A","exercises":[{"name":"Goblet squat","sets":3,"reps":"10-12","rpe":7,"rest":"60-90s","tempo":"3-1-1","notes":"Sit down between your heels, chest tall","video_url":""},{"name":"Dumbbell Romanian deadlift","sets":3,"reps":"10-12","rpe":7,"rest":"60-90s","tempo":"3-0-1","notes":"Push hips back, soft knees, flat back","video_url":""},{"name":"Incline push-up","sets":3,"reps":"6-10","rpe":7,"rest":"60s","tempo":"2-0-1","notes":"Hands on a bench or table, body straight","video_url":""},{"name":"One-arm dumbbell row","sets":3,"reps":"10-12 each arm","rpe":7,"rest":"60s","tempo":"2-1-1","notes":"Hand on a chair, pull to your hip","video_url":""},{"name":"Banded glute bridge","sets":3,"reps":"12-15","rpe":7,"rest":"60s","tempo":"2-1-1","notes":"Band above knees, push knees out","video_url":""},{"name":"Dead bug","sets":3,"reps":"8 each side","rpe":6,"rest":"45s","tempo":"","notes":"Lower back stays pressed down","video_url":""}]},{"name":"Day B","exercises":[{"name":"Dumbbell reverse lunge","sets":3,"reps":"8 each leg","rpe":7,"rest":"60-90s","tempo":"2-0-1","notes":"Hold a wall for balance if needed","video_url":""},{"name":"Dumbbell hip thrust","sets":3,"reps":"12-15","rpe":7,"rest":"60-90s","tempo":"2-1-1","notes":"Shoulders on the sofa, pause at the top","video_url":""},{"name":"Seated dumbbell shoulder press","sets":3,"reps":"10-12","rpe":7,"rest":"60s","tempo":"2-0-1","notes":"Sit tall, ribs down","video_url":""},{"name":"Band lat pulldown","sets":3,"reps":"12-15","rpe":7,"rest":"60s","tempo":"2-1-1","notes":"Anchor high, pull elbows to your sides","video_url":""},{"name":"Band lateral walk","sets":2,"reps":"10 steps each way","rpe":7,"rest":"45s","tempo":"","notes":"Stay low, toes forward","video_url":""},{"name":"Side plank (knees)","sets":3,"reps":"20s each side","rpe":6,"rest":"45s","tempo":"","notes":"Hips high","video_url":""}]},{"name":"Day C","exercises":[{"name":"Dumbbell sumo squat","sets":3,"reps":"12","rpe":7,"rest":"60-90s","tempo":"3-1-1","notes":"Wide stance, toes out, knees follow toes","video_url":""},{"name":"Single-leg glute bridge","sets":3,"reps":"10 each leg","rpe":7,"rest":"60s","tempo":"2-1-1","notes":"Drive through the heel","video_url":""},{"name":"Dumbbell floor press","sets":3,"reps":"10-12","rpe":7,"rest":"60s","tempo":"2-1-1","notes":"Pause when your elbows touch the floor","video_url":""},{"name":"Band face pull","sets":3,"reps":"15","rpe":6,"rest":"45s","tempo":"2-1-1","notes":"Pull to your forehead, thumbs back","video_url":""},{"name":"Dumbbell bent-over row","sets":3,"reps":"10-12","rpe":7,"rest":"60s","tempo":"2-1-1","notes":"Hinge forward, flat back","video_url":""},{"name":"Bird dog","sets":3,"reps":"8 each side","rpe":5,"rest":"45s","tempo":"","notes":"Slow and steady, hips level","video_url":""}]}]'::jsonb),
