  ('Upper Lower 4x (Gym)', 'Upper, Lower, Upper, Lower. For clients training 4 days a week at the gym.', 'Suggested week: Mon Upper A, Tue Lower A, Thu Upper B, Fri Lower B. RPE 7 means you could have done about 3 more reps. When you hit the top of the rep range on every set, go a little heavier next time.', '[{"name":"Upper A","exercises":[{"name":"Barbell bench press","sets":3,"reps":"6-8","rpe":7.5,"rest":"2-3 min","tempo":"2-1-1","notes":"Feet planted, touch mid-chest","video_url":""},{"name":"Seated cable row","sets":3,"reps":"8-10","rpe":7.5,"rest":"90s","tempo":"2-1-1","notes":"Chest up, squeeze shoulder blades","video_url":""},{"name":"Seated dumbbell shoulder press","sets":3,"reps":"8-10","rpe":7,"rest":"90s","tempo":"2-0-1","notes":"Back against the pad","video_url":""},{"name":"Lat pulldown","sets":3,"reps":"10-12","rpe":7,"rest":"90s","tempo":"2-1-1","notes":"Pull elbows to your back pockets","video_url":""},{"name":"Dumbbell curl","sets":2,"reps":"10-12","rpe":8,"rest":"60s","tempo":"2-0-2","notes":"No swinging","video_url":""},{"name":"Triceps rope pushdown","sets":2,"reps":"10-12","rpe":8,"rest":"60s","tempo":"2-0-1","notes":"Elbows pinned","video_url":""}]},{"name":"Lower A","exercises":[{"name":"Barbell back squat","sets":3,"reps":"6-8","rpe":7.5,"rest":"2-3 min","tempo":"3-1-1","notes":"Brace, knees follow toes","video_url":""},{"name":"Romanian deadlift","sets":3,"reps":"8-10","rpe":7,"rest":"2 min","tempo":"3-0-1","notes":"Flat back, hips back","video_url":""},{"name":"Dumbbell reverse lunge","sets":3,"reps":"8 each leg","rpe":7,"rest":"90s","tempo":"2-0-1","notes":"Front knee over the foot","video_url":""},{"name":"Lying leg curl","sets":3,"reps":"10-12","rpe":8,"rest":"60-90s","tempo":"2-0-2","notes":"Control the way down","video_url":""},{"name":"Standing calf raise","sets":3,"reps":"12-15","rpe":8,"rest":"60s","tempo":"2-1-2","notes":"Full stretch at the bottom","video_url":""}]},{"name":"Upper B","exercises":[{"name":"Incline dumbbell press","sets":3,"reps":"8-10","rpe":7.5,"rest":"90s","tempo":"3-0-1","notes":"Bench at about 30 degrees","video_url":""},{"name":"Assisted pull-up","sets":3,"reps":"6-10","rpe":7.5,"rest":"2 min","tempo":"2-0-1","notes":"Use the machine or a band, full range","video_url":""},{"name":"Chest-supported dumbbell row","sets":3,"reps":"10-12","rpe":7,"rest":"90s","tempo":"2-1-1","notes":"Chest on an incline bench","video_url":""},{"name":"Cable lateral raise","sets":3,"reps":"12-15","rpe":8,"rest":"60s","tempo":"2-0-2","notes":"Stop at shoulder height","video_url":""},{"name":"Face pull","sets":3,"reps":"12-15","rpe":7,"rest":"60s","tempo":"2-1-1","notes":"Thumbs back","video_url":""},{"name":"Dumbbell hammer curl","sets":2,"reps":"10-12","rpe":8,"rest":"60s","tempo":"2-0-2","notes":"No swinging","video_url":""}]},{"name":"Lower B","exercises":[{"name":"Trap bar deadlift","sets":3,"reps":"5","rpe":7,"rest":"2-3 min","tempo":"","notes":"Or a conventional deadlift. Push the floor away","video_url":""},{"name":"Leg press","sets":3,"reps":"10-12","rpe":8,"rest":"90s","tempo":"3-1-1","notes":"Don''t lock the knees","video_url":""},{"name":"Hip thrust","sets":3,"reps":"8-12","rpe":8,"rest":"90s","tempo":"2-1-1","notes":"Pause 1 second at the top","video_url":""},{"name":"Leg extension","sets":3,"reps":"12-15","rpe":8,"rest":"60s","tempo":"2-1-2","notes":"Squeeze at the top","video_url":""},{"name":"Seated calf raise","sets":3,"reps":"12-15","rpe":8,"rest":"60s","tempo":"2-1-2","notes":"Full stretch at the bottom","video_url":""},{"name":"Hanging knee raise","sets":3,"reps":"10","rpe":7,"rest":"60s","tempo":"","notes":"No swinging. Captain''s chair is fine","video_url":""}]}]'::jsonb),
  ('Upper Lower 4x (Home Gym)', 'Upper, Lower, Upper, Lower with a barbell, bench and dumbbells. No squat rack needed.', 'Suggested week: Mon Upper A, Tue Lower A, Thu Upper B, Fri Lower B. No rack or spotter, so never bench press a barbell: use dumbbells or the floor press. RPE 7 means you could have done about 3 more reps. When you hit the top of the rep range on every set, go a little heavier next time.', '[{"name":"Upper A","exercises":[{"name":"Dumbbell bench press","sets":3,"reps":"8-10","rpe":7.5,"rest":"90s","tempo":"3-0-1","notes":"Shoulder blades squeezed together","video_url":""},{"name":"Barbell bent-over row","sets":3,"reps":"8-10","rpe":7.5,"rest":"90s","tempo":"2-1-1","notes":"Hinge to 45 degrees, pull to your belly button","video_url":""},{"name":"Seated dumbbell shoulder press","sets":3,"reps":"8-10","rpe":7,"rest":"90s","tempo":"2-0-1","notes":"Sit tall on the bench","video_url":""},{"name":"One-arm dumbbell row","sets":3,"reps":"10-12 each arm","rpe":7,"rest":"60-90s","tempo":"2-1-1","notes":"Hand and knee on the bench","video_url":""},{"name":"Dumbbell curl","sets":2,"reps":"10-12","rpe":8,"rest":"60s","tempo":"2-0-2","notes":"No swinging","video_url":""},{"name":"Dumbbell overhead triceps extension","sets":2,"reps":"10-12","rpe":8,"rest":"60s","tempo":"2-0-1","notes":"Elbows point up","video_url":""}]},{"name":"Lower A","exercises":[{"name":"Dumbbell front squat","sets":3,"reps":"8-12","rpe":7.5,"rest":"2 min","tempo":"3-1-1","notes":"Dumbbells on shoulders, chest tall","video_url":""},{"name":"Barbell Romanian deadlift","sets":3,"reps":"8-10","rpe":7,"rest":"2 min","tempo":"3-0-1","notes":"Bar slides down your thighs","video_url":""},{"name":"Dumbbell reverse lunge","sets":3,"reps":"8 each leg","rpe":7,"rest":"90s","tempo":"2-0-1","notes":"Front knee over the foot","video_url":""},{"name":"Barbell hip thrust","sets":3,"reps":"10-12","rpe":8,"rest":"90s","tempo":"2-1-1","notes":"Upper back on the bench, pad the bar","video_url":""},{"name":"Single-leg calf raise","sets":3,"reps":"12 each leg","rpe":8,"rest":"45s","tempo":"2-1-2","notes":"Hold the wall, full stretch","video_url":""}]},{"name":"Upper B","exercises":[{"name":"Barbell floor press","sets":3,"reps":"6-8","rpe":7.5,"rest":"2 min","tempo":"2-1-1","notes":"Pause when your upper arms touch the floor","video_url":""},{"name":"Chest-supported dumbbell row","sets":3,"reps":"10-12","rpe":7,"rest":"90s","tempo":"2-1-1","notes":"Lie face down on the bench","video_url":""},{"name":"Push-up","sets":3,"reps":"As many as possible","rpe":8,"rest":"90s","tempo":"2-0-1","notes":"Stop 2 reps before your form breaks","video_url":""},{"name":"Dumbbell lateral raise","sets":3,"reps":"12-15","rpe":8,"rest":"60s","tempo":"2-0-2","notes":"Stop at shoulder height","video_url":""},{"name":"Dumbbell rear delt fly","sets":3,"reps":"12-15","rpe":8,"rest":"60s","tempo":"2-1-1","notes":"Hinge forward, lead with the elbows","video_url":""},{"name":"Dumbbell hammer curl","sets":2,"reps":"10-12","rpe":8,"rest":"60s","tempo":"2-0-2","notes":"No swinging","video_url":""}]},{"name":"Lower B","exercises":[{"name":"Barbell deadlift","sets":3,"reps":"5","rpe":7,"rest":"2-3 min","tempo":"","notes":"Bar over mid-foot, flat back","video_url":""},{"name":"Bulgarian split squat","sets":3,"reps":"8 each leg","rpe":8,"rest":"90s","tempo":"3-1-1","notes":"Rear foot on the bench, hold dumbbells","video_url":""},{"name":"Barbell glute bridge","sets":3,"reps":"10-12","rpe":8,"rest":"90s","tempo":"2-1-1","notes":"Pause at the top","video_url":""},{"name":"Dead bug","sets":3,"reps":"8 each side","rpe":6,"rest":"60s","tempo":"","notes":"Lower back stays pressed down","video_url":""}]}]'::jsonb),
  ('Dumbbells & Bands Upper Lower 4x (Home)', 'The next step after the Dumbbells & Bands full-body plan, once a client is consistent and wants 4 days.', 'Suggested week: Mon Upper A, Tue Lower A, Thu Upper B, Fri Lower B. When your dumbbells feel light, slow the lowering, add a pause, or do single-leg and single-arm versions. RPE 7 means you could have done about 3 more reps. When you hit the top of the rep range on every set, go a little heavier next time.', '[{"name":"Upper A","exercises":[{"name":"Dumbbell floor press","sets":3,"reps":"10-12","rpe":7.5,"rest":"60-90s","tempo":"3-1-1","notes":"Pause when your elbows touch the floor","video_url":""},{"name":"One-arm dumbbell row","sets":3,"reps":"10-12 each arm","rpe":7.5,"rest":"60s","tempo":"2-1-1","notes":"Hand on a chair, pull to your hip","video_url":""},{"name":"Seated dumbbell shoulder press","sets":3,"reps":"10-12","rpe":7,"rest":"60s","tempo":"2-0-1","notes":"Sit tall, ribs down","video_url":""},{"name":"Band lat pulldown","sets":3,"reps":"12-15","rpe":7,"rest":"60s","tempo":"2-1-1","notes":"Anchor high, elbows to your sides","video_url":""},{"name":"Dumbbell curl","sets":2,"reps":"12","rpe":8,"rest":"45s","tempo":"2-0-2","notes":"No swinging","video_url":""},{"name":"Band triceps pushdown","sets":2,"reps":"15","rpe":8,"rest":"45s","tempo":"2-0-1","notes":"Anchor high, elbows pinned","video_url":""}]},{"name":"Lower A","exercises":[{"name":"Pause goblet squat","sets":3,"reps":"10-12","rpe":7.5,"rest":"90s","tempo":"3-2-1","notes":"2-second pause at the bottom","video_url":""},{"name":"Dumbbell Romanian deadlift","sets":3,"reps":"10-12","rpe":7.5,"rest":"90s","tempo":"3-0-1","notes":"Flat back, hips back","video_url":""},{"name":"Dumbbell reverse lunge","sets":3,"reps":"10 each leg","rpe":7,"rest":"60-90s","tempo":"2-0-1","notes":"Hold a wall if needed","video_url":""},{"name":"Seated band hip abduction","sets":3,"reps":"15-20","rpe":8,"rest":"45s","tempo":"2-1-1","notes":"Band above knees, push out","video_url":""},{"name":"Single-leg calf raise","sets":3,"reps":"12 each leg","rpe":8,"rest":"45s","tempo":"2-1-2","notes":"Hold the wall","video_url":""}]},{"name":"Upper B","exercises":[{"name":"Push-up (incline or knees)","sets":3,"reps":"As many as possible","rpe":8,"rest":"60-90s","tempo":"2-0-1","notes":"Stop 2 reps before your form breaks","video_url":""},{"name":"Band seated row","sets":3,"reps":"12-15","rpe":7.5,"rest":"60s","tempo":"2-1-1","notes":"Squeeze shoulder blades","video_url":""},{"name":"Dumbbell lateral raise","sets":3,"reps":"12-15","rpe":8,"rest":"45s","tempo":"2-0-2","notes":"Stop at shoulder height","video_url":""},{"name":"Band face pull","sets":3,"reps":"15","rpe":7,"rest":"45s","tempo":"2-1-1","notes":"Thumbs back","video_url":""},{"name":"Dumbbell hammer curl","sets":2,"reps":"12","rpe":8,"rest":"45s","tempo":"2-0-2","notes":"No swinging","video_url":""}]},{"name":"Lower B","exercises":[{"name":"Bulgarian split squat","sets":3,"reps":"8 each leg","rpe":8,"rest":"90s","tempo":"3-1-1","notes":"Rear foot on the sofa or a chair","video_url":""},{"name":"Single-leg Romanian deadlift","sets":3,"reps":"8 each leg","rpe":7,"rest":"60-90s","tempo":"3-0-1","notes":"Hold a wall with the free hand","video_url":""},{"name":"Dumbbell hip thrust","sets":3,"reps":"12-15","rpe":8,"rest":"60-90s","tempo":"2-2-1","notes":"Shoulders on the sofa, 2-second squeeze","video_url":""},{"name":"Band lateral walk","sets":2,"reps":"10 steps each way","rpe":8,"rest":"45s","tempo":"","notes":"Stay low, toes forward","video_url":""},{"name":"Dead bug","sets":3,"reps":"8 each side","rpe":6,"rest":"45s","tempo":"","notes":"Lower back stays pressed down","video_url":""}]}]'::jsonb)
